<?php $requests = $requests ?? []; $user = $user ?? []; $my_requests = array_values(array_filter($requests, fn($r) => ($r['recipient_id'] ?? '') === ($user['id'] ?? ''))); ?><section class="content"><div class="split-heading"><div><p>Submit and track every request from one place.</p></div><button class="button primary" data-modal-open="request-modal">＋ New request</button></div><div class="panel table-panel"><table><thead><tr><th>Request</th><th>Hospital / location</th><th>Urgency</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach (array_reverse($my_requests) as $request): ?><tr><td><strong><?= h($request['id']) ?></strong><small><?= h($request['blood_group']) ?> · <?= h((string) $request['units']) ?> unit(s)</small></td><td><?= h($request['hospital']) ?></td><td><span class="urgency <?= strtolower($request['urgency']) ?>"><?= h($request['urgency']) ?></span></td><td><span class="badge <?= status_class($request['status']) ?>"><?= h($request['status']) ?></span></td><td><?= h($request['created']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$my_requests): ?><div class="empty">No requests yet. Start one when you need help.</div><?php endif; ?></div></section><div class="modal" id="request-modal"><div class="modal-box"><button class="modal-close" data-modal-close>×</button><span class="eyebrow">New blood request</span><h2>Tell us what is needed</h2><form method="post" class="form-stack"><input type="hidden" name="action" value="request"><div class="form-row"><label>Blood group<select name="blood_group"><?php foreach (['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $group): ?><option><?= $group ?></option><?php endforeach; ?></select></label><label>Units<input type="number" min="1" max="20" name="units" value="1"></label></div><label>Hospital / location<input required name="hospital" placeholder="Where should help arrive?"></label><label>Urgency<select name="urgency"><option>Routine</option><option>Urgent</option><option>Critical</option></select></label><label>Additional note<textarea name="note" rows="3" placeholder="Add relevant details..."></textarea></label><button class="button primary wide">Submit request <span>→</span></button></form></div></div>